+import { verifySessionToken, decodeToken, SessionToken } from "./session-tokens.ts";
+import { isRevoked } from "./revocation-cache.ts";
+
+export const validateEdgeSession = (encodedToken: string): SessionToken | null => {
+  const token = decodeToken(encodedToken);
+  if (!token) return null;
+
+  if (!verifySessionToken(token)) return null;
+  if (isRevoked(token.id)) return null;
+
+  return token;
+};
