+interface RevocationEntry {
+  timestamp: number;
+  expiresAt: number;
+}
+
+const REVOCATION_TTL = 70 * 1000; // 70 seconds (slightly longer than 60-second SLA)
+const revokedSessions = new Map<string, RevocationEntry>();
+
+export const markRevoked = (sessionId: string): void => {
+  const now = Date.now();
+  revokedSessions.set(sessionId, {
+    timestamp: now,
+    expiresAt: now + REVOCATION_TTL,
+  });
+};
+
+export const isRevoked = (sessionId: string): boolean => {
+  const entry = revokedSessions.get(sessionId);
+  if (!entry) return false;
+
+  const now = Date.now();
+  if (now > entry.expiresAt) {
+    revokedSessions.delete(sessionId);
+    return false;
+  }
+
+  return true;
+};
+
+export const clearExpired = (): void => {
+  const now = Date.now();
+  for (const [sessionId, entry] of revokedSessions.entries()) {
+    if (now > entry.expiresAt) {
+      revokedSessions.delete(sessionId);
+    }
+  }
+};
