--- /dev/null
+++ b/src/session-tokens.ts
@@ -0,0 +1,49 @@
+import crypto from "crypto";
+
+const SESSION_SECRET = process.env.SESSION_SECRET || "dev-secret-change-in-prod";
+
+export interface SessionToken {
+  id: string;
+  userId: string;
+  issuedAt: number;
+  signature: string;
+}
+
+export const createSessionToken = (
+  sessionId: string,
+  userId: string,
+): SessionToken => {
+  const issuedAt = Math.floor(Date.now() / 1000);
+  const payload = `${sessionId}:${userId}:${issuedAt}`;
+  const signature = crypto
+    .createHmac("sha256", SESSION_SECRET)
+    .update(payload)
+    .digest("hex");
+
+  return { id: sessionId, userId, issuedAt, signature };
+};
+
+export const verifySessionToken = (token: SessionToken): boolean => {
+  const payload = `${token.id}:${token.userId}:${token.issuedAt}`;
+  const expectedSignature = crypto
+    .createHmac("sha256", SESSION_SECRET)
+    .update(payload)
+    .digest("hex");
+  return crypto.timingSafeEqual(
+    Buffer.from(token.signature),
+    Buffer.from(expectedSignature),
+  );
+};
+
+export const encodeToken = (token: SessionToken): string => {
+  return Buffer.from(JSON.stringify(token)).toString("base64url");
+};
+
+export const decodeToken = (encoded: string): SessionToken | null => {
+  try {
+    const json = Buffer.from(encoded, "base64url").toString();
+    return JSON.parse(json);
+  } catch {
+    return null;
+  }
+};
